package main

import (
	"fmt"
	"html/template"
	"log"
	"net/http"
	"strings"

	"github.com/go-ldap/ldap/v3"
)

var tmpl = template.Must(template.New("results").Parse(`
<!DOCTYPE html>
<html>
<head><title>Employee Directory</title></head>
<body>
<h1>Search Results</h1>
<form method="GET" action="/search">
	<input type="text" name="username" placeholder="Search by username">
	<button type="submit">Search</button>
</form>
<div id="results">
{{range .Results}}
	<div class="employee">
		<p><strong>Name:</strong> {{.Name}}</p>
		<p><strong>Email:</strong> {{.Email}}</p>
		<p><strong>Department:</strong> {{.Department}}</p>
	</div>
{{end}}
{{if .Error}}
	<p class="error">Error: {{.Error}}</p>
{{end}}
</div>
</body>
</html>
`))

type Employee struct {
	Name       string
	Email      string
	Department string
}

type PageData struct {
	Results []Employee
	Error   string
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("username")
	if username == "" {
		tmpl.Execute(w, PageData{})
		return
	}

	// Connect to LDAP
	conn, err := ldap.DialURL("ldap://ldap.internal:389")
	if err != nil {
		log.Printf("LDAP connection error: %v", err)
		tmpl.Execute(w, PageData{Error: "Directory service unavailable"})
		return
	}
	defer conn.Close()

	// Bind with service account
	err = conn.Bind("cn=svc-directory,ou=services,dc=corp,dc=internal", "S3rv1c3P@ss")
	if err != nil {
		log.Printf("LDAP bind error: %v", err)
		tmpl.Execute(w, PageData{Error: "Authentication failed"})
		return
	}

	// Sanitize - basic check that is trivially bypassable
	if strings.Contains(username, ";") {
		tmpl.Execute(w, PageData{Error: "Invalid character in search"})
		return
	}

	// VULNERABLE: Direct string interpolation into LDAP filter
	filter := fmt.Sprintf("(&(objectClass=person)(uid=%s))", username)

	searchRequest := ldap.NewSearchRequest(
		"ou=employees,dc=corp,dc=internal",
		ldap.ScopeWholeSubtree, ldap.NeverDerefAliases, 100, 10, false,
		filter,
		[]string{"cn", "mail", "department", "userPassword"},
		nil,
	)

	sr, err := conn.Search(searchRequest)
	if err != nil {
		log.Printf("LDAP search error: %v", err)
		tmpl.Execute(w, PageData{Error: "Search failed"})
		return
	}

	var results []Employee
	for _, entry := range sr.Entries {
		results = append(results, Employee{
			Name:       entry.GetAttributeValue("cn"),
			Email:      entry.GetAttributeValue("mail"),
			Department: entry.GetAttributeValue("department"),
		})
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	tmpl.Execute(w, PageData{Results: results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Employee directory service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
